
REVOKE EXECUTE ON FUNCTION public.frequency_coverage(text) FROM anon;

INSERT INTO public.sentence_patterns (language, cefr_level, usage_rank, template, slots, explanation, example, example_translation) VALUES
-- FRENCH
('fr','a1',1,'C''est ___.','[{"name":"noun","type":"noun_or_phrase"}]','Identify or name something.','C''est un livre.','It''s a book.'),
('fr','a1',2,'Je suis ___.','[{"name":"adjective","type":"adjective_or_noun"}]','Say what or how you are.','Je suis fatigué.','I am tired.'),
('fr','a1',3,'J''ai ___.','[{"name":"noun","type":"noun_or_phrase"}]','Say what you have.','J''ai une question.','I have a question.'),
('fr','a1',4,'Je voudrais ___, s''il vous plaît.','[{"name":"object","type":"noun_or_phrase"}]','Politely ask for something.','Je voudrais un café, s''il vous plaît.','I would like a coffee, please.'),
('fr','a1',5,'Je ne ___ pas.','[{"name":"verb","type":"verb"}]','Make a simple negative statement.','Je ne comprends pas.','I don''t understand.'),
('fr','a1',6,'Où est ___ ?','[{"name":"noun","type":"noun_or_phrase"}]','Ask where something is.','Où est la gare ?','Where is the station?'),
('fr','a1',7,'Il y a ___.','[{"name":"noun","type":"noun_or_phrase"}]','Say that something exists or is present.','Il y a un problème.','There is a problem.'),
('fr','a1',8,'J''aime ___.','[{"name":"thing","type":"noun_or_verb"}]','Say what you like.','J''aime voyager.','I like travelling.'),
('fr','a2',9,'Hier, j''ai ___.','[{"name":"participle","type":"past_participle"}]','Talk about something you did in the past.','Hier, j''ai vu ce film.','Yesterday I saw that film.'),
('fr','a2',10,'Je vais ___.','[{"name":"verb","type":"infinitive"}]','Talk about what you are going to do.','Je vais partir demain.','I''m going to leave tomorrow.'),
('fr','a2',11,'Je dois ___.','[{"name":"verb","type":"infinitive"}]','Express obligation.','Je dois travailler ce soir.','I have to work tonight.'),
('fr','a2',12,'___ est plus ___ que ___.','[{"name":"subject","type":"noun"},{"name":"adjective","type":"adjective"},{"name":"comparison","type":"noun"}]','Compare two things.','Le train est plus rapide que le bus.','The train is faster than the bus.'),
('fr','a2',13,'Je ___ parce que ___.','[{"name":"clause","type":"clause"},{"name":"reason","type":"clause"}]','Give a reason.','Je reste parce que j''ai du travail.','I''m staying because I have work.'),
('fr','a2',14,'Est-ce que tu peux ___ ?','[{"name":"verb","type":"infinitive"}]','Ask someone to do something.','Est-ce que tu peux m''aider ?','Can you help me?'),
('fr','b1',15,'Je pense que ___.','[{"name":"clause","type":"clause"}]','Give an opinion.','Je pense que c''est une bonne idée.','I think it''s a good idea.'),
('fr','b1',16,'Si ___, je ___.','[{"name":"condition","type":"clause"},{"name":"result","type":"clause"}]','Talk about a condition and its result.','Si j''ai le temps, je viendrai.','If I have time, I''ll come.'),
('fr','b1',17,'Il faut que je ___.','[{"name":"verb","type":"subjunctive"}]','Express necessity with the subjunctive.','Il faut que je parte.','I need to leave.'),
('fr','b1',18,'Ce qui m''intéresse, c''est ___.','[{"name":"topic","type":"noun_or_phrase"}]','Highlight what matters to you.','Ce qui m''intéresse, c''est la musique.','What interests me is music.'),
('fr','b2',19,'Bien que ___, ___.','[{"name":"concession","type":"clause"},{"name":"main","type":"clause"}]','Concede a point before making yours.','Bien que ce soit difficile, ça vaut la peine.','Although it''s difficult, it''s worth it.'),
('fr','b2',20,'Si j''avais ___, je ___erais.','[{"name":"condition","type":"clause"},{"name":"result","type":"clause"}]','Talk about an unreal or hypothetical situation.','Si j''avais plus d''argent, je voyagerais.','If I had more money, I would travel.'),
('fr','c1',21,'Non seulement ___, mais aussi ___.','[{"name":"first","type":"clause"},{"name":"second","type":"clause"}]','Add emphasis by stacking two points.','Non seulement il parle français, mais aussi russe.','Not only does he speak French, but also Russian.'),
('fr','c2',22,'Quoi qu''il en soit, ___.','[{"name":"clause","type":"clause"}]','Move past an objection in formal discussion.','Quoi qu''il en soit, la décision est prise.','Be that as it may, the decision is made.'),
