('es','a1',4,'Quisiera ___, por favor.','[{"name":"object","type":"noun_or_phrase"}]','Politely ask for something.','Quisiera un café, por favor.','I would like a coffee, please.'),
('es','a1',5,'No ___.','[{"name":"verb","type":"verb"}]','Make a simple negative statement.','No entiendo.','I don''t understand.'),
('es','a1',6,'¿Dónde está ___?','[{"name":"noun","type":"noun_or_phrase"}]','Ask where something is.','¿Dónde está la estación?','Where is the station?'),
('es','a1',7,'Hay ___.','[{"name":"noun","type":"noun_or_phrase"}]','Say that something exists.','Hay un problema.','There is a problem.'),
('es','a1',8,'Me gusta ___.','[{"name":"thing","type":"noun_or_verb"}]','Say what you like.','Me gusta viajar.','I like travelling.'),
('es','a2',9,'Ayer ___.','[{"name":"verb","type":"past_tense"}]','Talk about something you did.','Ayer vi esa película.','Yesterday I saw that film.'),
('es','a2',10,'Voy a ___.','[{"name":"verb","type":"infinitive"}]','Talk about your plans.','Voy a salir mañana.','I''m going to leave tomorrow.'),
('es','a2',11,'Tengo que ___.','[{"name":"verb","type":"infinitive"}]','Express obligation.','Tengo que trabajar esta noche.','I have to work tonight.'),
('es','a2',12,'___ es más ___ que ___.','[{"name":"subject","type":"noun"},{"name":"adjective","type":"adjective"},{"name":"comparison","type":"noun"}]','Compare two things.','El tren es más rápido que el autobús.','The train is faster than the bus.'),
('es','a2',13,'___ porque ___.','[{"name":"clause","type":"clause"},{"name":"reason","type":"clause"}]','Give a reason.','Me quedo porque tengo trabajo.','I''m staying because I have work.'),
('es','a2',14,'¿Puedes ___?','[{"name":"verb","type":"infinitive"}]','Ask someone to do something.','¿Puedes ayudarme?','Can you help me?'),
('es','b1',15,'Creo que ___.','[{"name":"clause","type":"clause"}]','Give an opinion.','Creo que es buena idea.','I think it''s a good idea.'),
('es','b1',16,'Si ___, ___.','[{"name":"condition","type":"clause"},{"name":"result","type":"clause"}]','Talk about a condition and its result.','Si tengo tiempo, iré.','If I have time, I''ll go.'),
('es','b1',17,'Es necesario que ___.','[{"name":"verb","type":"subjunctive"}]','Express necessity with the subjunctive.','Es necesario que vengas.','It''s necessary that you come.'),
('es','b1',18,'Lo que me interesa es ___.','[{"name":"topic","type":"noun_or_phrase"}]','Highlight what matters to you.','Lo que me interesa es la música.','What interests me is music.'),
('es','b2',19,'Aunque ___, ___.','[{"name":"concession","type":"clause"},{"name":"main","type":"clause"}]','Concede a point before making yours.','Aunque sea difícil, vale la pena.','Although it''s difficult, it''s worth it.'),
('es','b2',20,'Si tuviera ___, ___ría.','[{"name":"condition","type":"clause"},{"name":"result","type":"clause"}]','Talk about a hypothetical situation.','Si tuviera más dinero, viajaría.','If I had more money, I would travel.'),
('es','c1',21,'No sólo ___, sino también ___.','[{"name":"first","type":"clause"},{"name":"second","type":"clause"}]','Stack two points for emphasis.','No sólo habla español, sino también ruso.','Not only does he speak Spanish, but also Russian.'),
('es','c2',22,'Sea como sea, ___.','[{"name":"clause","type":"clause"}]','Move past an objection in formal discussion.','Sea como sea, la decisión está tomada.','Be that as it may, the decision is made.'),
